fn todo_state_json(account: &todo_program_client::accounts::TodoStateZc) -> Value {
	json!({
		"owner": account.owner.to_string(),
		"bump": account.bump,
		"completed": account.completed.get(),
		"digest": account.digest.iter().map(|byte| format!("{byte:02x}")).collect::<String>(),
	})
}

fn print_value(json_output: bool, name: &str, address: &Pubkey, value: &Value) {
	if json_output {
		println!(
			"{}",
			serde_json::to_string_pretty(value).unwrap_or_default()
		);
		return;
	}

	println!("{name} {address}");
	if let Some(fields) = value.as_object() {
		for (key, value) in fields {
			println!("  {key}: {value}");
		}
	}
}
